mapper.select:
SELECT PORTFOLIO_ID portfolioId, PORTFOLIO_NAME portfolioName FROM PTL_PORTFOLIO
AND PORTFOLIO_NAME LIKE CONCAT('%',CONCAT(#{filter},'%'))
union SELECT ppa.PORTFOLIO_ID portfolioId, ptl.PORTFOLIO_NAME portfolioName FROM PTL_PORTFOLIO_AUTHORITY ppa INNER join PTL_PORTFOLIO ptl ON ptl.PORTFOLIO_ID = ppa.PORTFOLIO_ID WHERE ppa.USER_ID = #{userId,jdbcType=VARCHAR}

SELECT PORTFOLIO_ID id, PORTFOLIO_NAME text FROM PTL_PORTFOLIO
AND PORTFOLIO_ID = #{initValue}
AND PORTFOLIO_ID LIKE CONCAT('%',CONCAT(#{search},'%')) OR PORTFOLIO_NAME LIKE CONCAT('%',CONCAT(#{search},'%'))

SELECT SEC_ACCT_ID id, SEC_ACCT_NAME text FROM STL_SEC_ACCT_INFO
SEC_ACCT_ID LIKE CONCAT('%',CONCAT(#{search},'%'))
SEC_ACCT_ID = #{initValue}

SELECT SEC.SEC_ACCT_NAME secAcctName, SEC.REGIST_ORG registOrg, SEC.REC_ACCT_ID recAcctId, SEC.TRD_ACCT_ID trdAcctId, SEC.SEC_ACCT_SOURCE secAcctSource, CAP.ACCT_NAME acctName FROM STL_SEC_ACCT_INFO SEC
LEFT JOIN
STL_CAPACCT_INFO CAP ON SEC.TRD_ACCT_ID = CAP.ACCT_NO WHERE SEC.SEC_ACCT_ID = #{secAcctNo}

SELECT
    DISTINCT PTL_BAG_ID
FROM
    PTL_PARAM_POOL_CONFIG

	(CLASSIFY_DIMENSION = #{classify_dimension_01}
	AND CLASSIFY_DIMENSION_VAL LIKE CONCAT('%',CONCAT(#{dimension_01},'%')))
	OR (CLASSIFY_DIMENSION = #{classify_dimension_02}
	AND CLASSIFY_DIMENSION_VAL LIKE CONCAT('%',CONCAT(#{dimension_02},'%')))
	OR (CLASSIFY_DIMENSION = #{classify_dimension_03}
	AND CLASSIFY_DIMENSION_VAL LIKE CONCAT('%',CONCAT(#{dimension_03},'%')))
	OR (CLASSIFY_DIMENSION = #{classify_dimension_04}
	AND CLASSIFY_DIMENSION_VAL LIKE CONCAT('%',CONCAT(#{dimension_04},'%')))

SELECT PORTFOLIO_ID portfolioId
FROM PTL_PORTFOLIO_AUTHORITY


		USER_ID = #{userId}

SELECT INSTITUTION_CODE code, INSTITUTION_NAME name, UPPER_INSTITUTION_CODE upperCode FROM SYS_INSTITUTION
INSTITUTION_CODE IN
#{item}

SELECT DEPT_CODE code, DEPT_NAME name, CASE WHEN UPPER_DEPT_CODE IS NULL THEN INSTITUTION_CODE ELSE UPPER_DEPT_CODE END AS upperCode FROM SYS_DEPARTMENT
INSTITUTION_CODE IN
#{item}

SELECT SYS_USER.USER_NAME code, SYS_USER.REAL_NAME name, SYS_USER.DEPT_CODE upperCode FROM SYS_USER SYS_USER
INNER JOIN SYS_DEPARTMENT ON SYS_USER.DEPT_CODE = SYS_DEPARTMENT.DEPT_CODE
SYS_DEPARTMENT.INSTITUTION_CODE = #{institutionCode}

SELECT DISTINCT A.PORTFOLIO_ID id, A.PORTFOLIO_NAME text, B.IS_GUARANTEE object FROM PTL_PORTFOLIO A LEFT JOIN PA_PTL_PORTFOLIO B ON A.PORTFOLIO_ID = B.PORTFOLIO_ID
PORTFOLIO_TYPE != '01'
AND (A.PORTFOLIO_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) OR A.PORTFOLIO_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )
AND A.PORTFOLIO_TYPE = #{portfolioType}
union all SELECT DISTINCT A.PORTFOLIO_ID id, A.PORTFOLIO_NAME text, B.IS_GUARANTEE object FROM PTL_PORTFOLIO A LEFT JOIN PA_PTL_PORTFOLIO B ON A.PORTFOLIO_ID = B.PORTFOLIO_ID
INNER JOIN PTL_PORTFOLIO_AUTHORITY ON PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID = A.PORTFOLIO_ID AND USER_ID = #{userId}
PORTFOLIO_TYPE = '01'
AND (A.PORTFOLIO_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) OR A.PORTFOLIO_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )
AND A.PORTFOLIO_TYPE = #{portfolioType}

mapper.insert:
insert into PTL_PORTFOLIO_AUTHORITY (PORTFOLIO_ID, USER_ID, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) select a.* from(
select #{ptlPort.portfolioId,jdbcType=VARCHAR}, #{ptlPort.userId,jdbcType=VARCHAR}, #{ptlPort.createUser,jdbcType=VARCHAR}, #{ptlPort.createDept,jdbcType=VARCHAR}, #{ptlPort.createTime,jdbcType=TIMESTAMP}, #{ptlPort.updateUser,jdbcType=VARCHAR}, #{ptlPort.updateTime,jdbcType=TIMESTAMP} from dual
) a

